    }

    function reattachTabbableElements() {
        const vimTabbableElements = Array.from(
            element.querySelectorAll(queryString) as NodeListOf<HTMLElement>,
        ).filter(isElementVisible)

        for (const el of vimTabbableElements) {
            el.onfocus = () => {
                vimFocusElement(el)
                onElementFocus?.(el)
            }
